css:
.card {
  background-color: #131c25;
  border: 3px solid #659AD2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  font-weight: 700;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  padding: 30px 20px;
  color: #659AD2;
  border-radius: 45px;
}

.App-logo {
  pointer-events: none;
  width: 140px;
  margin-bottom: 20px;
}

.App-button {
  padding: 10px 20px;
  background-color: transparent;
  color: #659AD2;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  font-size: 15px;
  border: 3px solid #659AD2;
  border-radius: 5em;
  margin-top: 20px;
  transition: 0.2s;
}

.App-button:hover {
  color: #282c34;
  background-color: #659AD2;
}
